export const title = "Will an Over-the-Door Organizer Stop Your Door From Closing?";
export const metaTitle = "Will an Over-the-Door Organizer Stop Your Door";
export const metaDescription = "Keep normal door closure and swing. Practical measurements, original diagrams and fit checks for small-room storage in small workspaces.";
export const author = "Jamie Cole, Lead Product Researcher";
